/* Relais du mode secours : le kit (page ouverte sur un poste) demande ici les copies du document Grist,
   que le navigateur ne peut pas lire directement. Paramètres de la demande : cle, quoi =
   ping | dossiers | empreinte | base. Les erreurs sont renvoyées au kit (jamais d'arrêt du workflow,
   sinon la réponse partirait sans l'en-tête qui autorise la page locale). */

// ===== À RÉGLER =====
const CLE_KIT = 'changez-moi';                          // clé à saisir dans les réglages du kit (choisissez-la longue)
const API_GRIST = 'https://grist.numerique.gouv.fr/o/crise/api';   // serveur et organisation, suivis de /api
const DOC = 'identifiant-du-document';                  // dans l'adresse du document : …/o/crise/<identifiant>/…
const CLE_GRIST = 'cle-api-grist';                      // compte Grist qui a accès au document (Paramètres du compte › Clé d'API)
// =====================

const q = $input.first().json.query || {};
const rep = (statut, corps) => [{ json: { statut, corps, binaire: false } }];
if (!q.cle || q.cle !== CLE_KIT) return rep(403, { erreur: 'clé refusée' });
const quoi = q.quoi || 'ping';
const t0 = Date.now();

const grist = async (chemin, o = {}) => {
  const url = `${API_GRIST}/docs/${DOC}${chemin}`;
  let r;
  try {
    r = await this.helpers.httpRequest({ url, method: o.method || 'GET', body: o.body, json: !o.binaire, encoding: o.binaire ? 'arraybuffer' : undefined,
      headers: { Authorization: `Bearer ${CLE_GRIST}`, ...(o.body ? { 'Content-Type': 'application/json' } : {}) }, returnFullResponse: true, timeout: 120000 });
  } catch (e) { throw new Error(`${chemin.split('?')[0]} : ${e.message}`); }
  let corps = r.body;
  if (o.binaire) return corps;
  if (typeof corps === 'string') { try { corps = JSON.parse(corps); } catch (_) {} }
  if (!corps || typeof corps !== 'object') throw new Error(`${chemin.split('?')[0]} : réponse inattendue (HTTP ${r.statusCode}, ${(r.headers || {})['content-type'] || '?'}) — vérifiez API_GRIST et DOC`);
  return corps;
};
const lignes = async t => {
  const c = await grist(`/tables/${encodeURIComponent(t)}/records`);
  if (!Array.isArray(c.records)) throw new Error(`table ${t} : réponse sans lignes`);
  return c.records;
};
// empreinte courte et stable (FNV-1a), sans module externe
const empreinte = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0') + '-' + s.length.toString(36); };

// tables « vivantes » : tables des réponses (Config, clé general) et leurs sous-tables (questions tableau,
// et toute table qui a une colonne de référence vers une table des réponses)
async function structure() {
  const tables = ((await grist('/tables')).tables || []).map(t => t.id);
  const colonnes = {};
  for (const t of tables) colonnes[t] = ((await grist(`/tables/${encodeURIComponent(t)}/columns`)).columns || []).map(c => ({ id: c.id, type: (c.fields || {}).type || '' }));
  const config = tables.includes('Config') ? await lignes('Config') : [];
  const valeur = cle => { const l = config.find(x => (x.fields || {}).Cle === cle); try { return l && l.fields.Valeur ? JSON.parse(l.fields.Valeur) : null; } catch (_) { return null; } };
  const g = valeur('general') || {};
  const reponses = [g.reponses || 'Reponses', ...((Array.isArray(g.autres_champs) ? g.autres_champs : []).map(e => e && e.reponses))].filter(t => t && tables.includes(t));
  const vivantes = new Set(reponses);
  for (const t of tables) if (colonnes[t].some(c => reponses.some(r => c.type === `Ref:${r}` || c.type === `RefList:${r}`))) vivantes.add(t);
  if (tables.includes('Formulaires')) for (const f of await lignes('Formulaires')) for (const k of ['Publie', 'Brouillon']) {
    let conf = null; try { conf = JSON.parse((f.fields || {})[k] || 'null'); } catch (_) {}
    for (const b of (conf && conf.blocs) || []) { const st = b && b.reglages && b.reglages.tableau && b.reglages.tableau.table; if (st && tables.includes(st)) vivantes.add(st); }
  }
  return { tables, colonnes, config, valeur, reponses, vivantes: [...vivantes] };
}

try {
  if (quoi === 'ping') {
    const d = await grist('');
    return rep(200, { format: 'kit-secours-ping', document: d.name || DOC, heure: new Date().toISOString(), duree_grist_ms: Date.now() - t0 });
  }
  if (quoi === 'dossiers') {
    const s = await structure();
    if (!s.reponses.length) return rep(502, { erreur: 'aucune table des réponses trouvée (clé general de Config)' });
    const tables = {}, compte = {};
    for (const t of s.vivantes) { const r = await lignes(t); tables[t] = { records: r }; compte[t] = r.length; }
    return rep(200, { format: 'kit-secours-instantane', version: 1, complement: true, genere_le: new Date().toISOString(), document: DOC,
      reponses: s.reponses, compte, secours: s.valeur('secours'), duree_grist_ms: Date.now() - t0, tables });
  }
  if (quoi === 'empreinte') {
    // structure (tables, colonnes), configuration (sauf la clé « secours », qui bouge à chaque réintégration)
    // et, pour chaque table hors tables vivantes : nombre de lignes, plus grand numéro, nombre total de caractères
    const s = await structure();
    const autres = s.tables.filter(t => !s.vivantes.includes(t));
    const parts = [JSON.stringify(s.colonnes), JSON.stringify(s.config.filter(l => (l.fields || {}).Cle !== 'secours').map(l => [l.id, l.fields]))];
    let mesure = 'sql';
    try {
      const sel = autres.map(t => {
        const cols = s.colonnes[t].filter(c => !c.id.startsWith('gristHelper')).map(c => `LENGTH(COALESCE("${c.id.replace(/"/g, '""')}", ''))`);
        return `SELECT '${t.replace(/'/g, "''")}' AS t, COUNT(*) AS n, MAX(id) AS m, TOTAL(${cols.length ? cols.join(' + ') : '0'}) AS c FROM "${t.replace(/"/g, '""')}"`;
      });
      const r = sel.length ? await grist('/sql', { method: 'POST', body: { sql: sel.join(' UNION ALL ') } }) : { records: [] };
      parts.push(JSON.stringify((r.records || []).map(x => x.fields)));
    } catch (e) { mesure = `structure et configuration seulement (${e.message})`; }
    return rep(200, { format: 'kit-secours-empreinte', empreinte: empreinte(parts.join('|')), mesure, tables_base: autres.length, duree_grist_ms: Date.now() - t0 });
  }
  if (quoi === 'base') {
    const b = Buffer.from(await grist('/download?nohistory=true&template=false', { binaire: true }));
    if (b.length < 1024 || b.subarray(0, 15).toString() !== 'SQLite format 3') return rep(502, { erreur: `téléchargement du document : fichier inattendu (${b.length} octets)` });
    return [{ json: { statut: 200, binaire: true, taille: b.length }, binary: { data: { data: b.toString('base64'), mimeType: 'application/octet-stream', fileName: 'instantane-base.grist' } } }];
  }
  return rep(400, { erreur: `demande inconnue : ${quoi}` });
} catch (e) {
  return rep(502, { erreur: `lecture de Grist impossible : ${e.message}` });
}
